python3 << 'EOF'
import xml.etree.ElementTree as ET

BPMN = "http://www.omg.org/spec/BPMN/20100524/MODEL"
BPMNDI = "http://www.omg.org/spec/BPMN/20100524/DI"
DC = "http://www.omg.org/spec/DD/20100524/DC"
DI = "http://www.omg.org/spec/DD/20100524/DI"
UIPATH = "http://uipath.org/schema/bpmn"

tree = ET.parse('/work/output/artifacts/skill-bpmn-callactivity-agentic-process/CallActivityAgenticBpmn/CallActivityAgenticBpmn.bpmn')
root = tree.getroot()

errors = []
warnings = []

# CHECK 1: Root is definitions with required namespaces
tag = root.tag
assert 'definitions' in tag, f"Root is not definitions: {tag}"
assert f'{{{BPMN}}}' in tag or 'definitions' in tag
print(f"[OK] Root element: {tag}")

# Collect all ids
all_ids = {}
for elem in root.iter():
    eid = elem.get('id')
    if eid:
        all_ids[eid] = elem.tag

print(f"[OK] All IDs: {list(all_ids.keys())}")

# CHECK 2: BPMNDiagram present
diagrams = root.findall(f'.//{{{BPMNDI}}}BPMNDiagram')
print(f"[OK] BPMNDiagram count: {len(diagrams)}")
if len(diagrams) != 1:
    errors.append("Expected exactly 1 BPMNDiagram")

# Collect shapes and edges
shapes = {s.get('bpmnElement') for s in root.iter(f'{{{BPMNDI}}}BPMNShape')}
edges = {e.get('bpmnElement') for e in root.iter(f'{{{BPMNDI}}}BPMNEdge')}
print(f"[OK] Shapes for: {shapes}")
print(f"[OK] Edges for: {edges}")

# CHECK: All flow nodes have shapes
proc = root.find(f'{{{BPMN}}}process')
flow_nodes = []
for child in proc:
    tag_local = child.tag.split('}')[-1] if '}' in child.tag else child.tag
    if tag_local in ('startEvent', 'endEvent', 'callActivity', 'serviceTask', 'userTask', 'task', 'scriptTask', 'subProcess', 'exclusiveGateway', 'parallelGateway', 'inclusiveGateway', 'eventBasedGateway', 'intermediateCatchEvent', 'intermediateThrowEvent', 'boundaryEvent', 'receiveTask', 'sendTask', 'businessRuleTask', 'manualTask'):
        nid = child.get('id')
        flow_nodes.append(nid)
        if nid not in shapes:
            errors.append(f"Node {nid} ({tag_local}) has no BPMNShape")
        else:
            print(f"[OK] Shape present for {nid}")

# CHECK: All sequence flows have edges
flows = []
for child in proc:
    if child.tag == f'{{{BPMN}}}sequenceFlow':
        fid = child.get('id')
        flows.append(fid)
        if fid not in edges:
            errors.append(f"SequenceFlow {fid} has no BPMNEdge")
        else:
            print(f"[OK] Edge present for {fid}")

# CHECK 3: All sourceRef/targetRef resolve
for child in proc:
    if child.tag == f'{{{BPMN}}}sequenceFlow':
        src = child.get('sourceRef')
        tgt = child.get('targetRef')
        if src not in all_ids:
            errors.append(f"Flow {child.get('id')}: sourceRef={src} not found")
        else:
            print(f"[OK] sourceRef {src} resolves")
        if tgt not in all_ids:
            errors.append(f"Flow {child.get('id')}: targetRef={tgt} not found")
        else:
            print(f"[OK] targetRef {tgt} resolves")

# CHECK 4: No XOR gateway in this file, skip gateway condition check
gateways = [c for c in proc if 'Gateway' in c.tag]
print(f"[OK] Gateways: {[g.get('id') for g in gateways]} (none expected for linear flow)")

# CHECK 5: Each activity/event has at most one incoming flow
incoming_count = {}
for child in proc:
    for inc in child.findall(f'{{{BPMN}}}incoming'):
        nid = child.get('id')
        incoming_count[nid] = incoming_count.get(nid, 0) + 1
for nid, cnt in incoming_count.items():
    if cnt > 1:
        errors.append(f"Node {nid} has {cnt} incoming flows (FAKE_JOIN)")
    else:
        print(f"[OK] Node {nid} incoming count: {cnt}")

# CHECK 6: No event subprocesses to check
event_subprocs = [c for c in proc if c.tag == f'{{{BPMN}}}subProcess' and c.get('triggeredByEvent') == 'true']
print(f"[OK] Event subprocesses: {len(event_subprocs)} (none expected)")

# CHECK 7: uipath:type child on callActivity payload
ns = {'uipath': UIPATH}
call_acts = [c for c in proc if c.tag == f'{{{BPMN}}}callActivity']
for ca in call_acts:
    ext = ca.find(f'{{{BPMN}}}extensionElements')
    if ext is not None:
        act = ext.find(f'{{{UIPATH}}}activity')
        if act is not None:
            t = act.find(f'{{{UIPATH}}}type')
            if t is None:
                errors.append(f"callActivity {ca.get('id')}: uipath:activity has no uipath:type child")
            else:
                print(f"[OK] uipath:type on callActivity: value={t.get('value')}")

# CHECK 8: No double-hyphen in XML (already confirmed by parse)
with open('/work/output/artifacts/skill-bpmn-callactivity-agentic-process/CallActivityAgenticBpmn/CallActivityAgenticBpmn.bpmn') as f:
    raw = f.read()
if '--' in raw.replace('<?xml', '').replace('UTF-8"?>', ''):
    # Only flag if -- appears in actual XML comment content
    import re
    comments = re.findall(r'<!--(.*?)-->', raw, re.DOTALL)
    for c in comments:
        if '--' in c:
            errors.append(f"XML comment contains '--': {c[:60]}")
print(f"[OK] No double-hyphen in XML comments")

# CHECK: callActivity uses bpmn:callActivity (not serviceTask)
for ca in call_acts:
    print(f"[OK] {ca.get('id')} is bpmn:callActivity (correct for StartAgenticProcess)")

print()
if errors:
    print("ERRORS:")
    for e in errors:
        print(f"  ERROR: {e}")
else:
    print("STRUCTURAL CHECKLIST: ALL CHECKS PASSED")
EOF
